select jsonb_build_object('revision',(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd'),'entries',(select jsonb_agg(to_jsonb(t)) from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2')),'inventories',coalesce((select jsonb_agg(to_jsonb(t)) from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and payload#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2')),'[]'::jsonb),'merchants',coalesce((select jsonb_agg(to_jsonb(t)) from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and deleted_at is null and exists(select 1 from jsonb_array_elements(case when jsonb_typeof(t.payload->'inventory')='array' then t.payload->'inventory' else '[]'::jsonb end)i where i#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2'))),'[]'::jsonb),'versions',coalesce((select jsonb_agg(to_jsonb(t)) from public.campaign_character_versions t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and character_id in(select parent_id from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and payload#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2'))),'[]'::jsonb),'guards',jsonb_build_object('content',(select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by campaign_id,kind,content_key),'')) from public.campaign_content_entries t where ((campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2'))or(campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and deleted_at is null and exists(select 1 from jsonb_array_elements(case when jsonb_typeof(t.payload->'inventory')='array' then t.payload->'inventory' else '[]'::jsonb end)i where i#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2')))) is not true),'shared',(select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by kind,content_key),'')) from public.official_content_entries t where true),'fragments',(select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by campaign_id,fragment_kind,parent_id,entity_id),'')) from public.campaign_state_fragments t where (campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and payload#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2')) is not true),'versions',(select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by campaign_id,character_id),'')) from public.campaign_character_versions t where (campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and character_id in(select parent_id from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and payload#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2'))) is not true),'campaigns',(select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by id),'')) from public.campaigns t where id<>'9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd'))) as snapshot;